document.addEventListener('DOMContentLoaded', () => {
    // 1. Manejo de la pantalla de bienvenida y la animación principal
    const welcomeScreen = document.getElementById('welcome-screen');
    const startBtn = document.getElementById('start-btn');

    startBtn.addEventListener('click', () => {
        // Desvanece el GIF
        welcomeScreen.style.opacity = '0';
        
        setTimeout(() => {
            // Oculta el contenedor del GIF por completo
            welcomeScreen.style.display = 'none';
            
            // Activa la animación del contenido principal (título y mapa)
            document.body.classList.add('content-active');
            
        }, 500); 
    });

    // 2. Conectar las provincias del SVG con los datos
    const pathsProvincias = document.querySelectorAll('.provincia-svg');

    pathsProvincias.forEach(path => {
        path.addEventListener('click', (e) => {
            const idProvincia = e.target.id; 
            const datosProvincia = provinciasData.find(p => p.id === idProvincia);

            if (datosProvincia) {
                mostrarInfo(datosProvincia, e.target);
            }
        });
    });

    // 3. Función final para actualizar el panel con la bandera
    function mostrarInfo(provincia, pathElement) {
        document.querySelectorAll('.provincia-svg').forEach(p => p.classList.remove('active'));
        pathElement.classList.add('active');

        document.querySelector('.placeholder-text').style.display = 'none';

        // Capturamos los elementos del HTML
        const flagEl = document.getElementById('prov-flag'); 
        const nameEl = document.getElementById('prov-name');
        const capEl = document.getElementById('prov-capital');
        const popEl = document.getElementById('prov-pop');
        const econEl = document.getElementById('prov-econ');

        // Inyectamos los datos
        flagEl.src = provincia.bandera; 
        nameEl.textContent = provincia.nombre;
        capEl.textContent = provincia.capital;
        popEl.textContent = provincia.poblacion;
        econEl.textContent = provincia.economia;

        // Los hacemos visibles
        flagEl.style.display = 'block'; 
        nameEl.style.display = 'block';
        capEl.style.display = 'inline';
        popEl.style.display = 'inline';
        econEl.style.display = 'inline';

        // Scroll suave hacia el panel en dispositivos móviles
        if (window.innerWidth <= 768) {
            const panelInfo = document.querySelector('.info-panel');
            panelInfo.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
    }
});
// Función para mostrar la información en la caja de abajo

function mostrarInfo(lugar) {
  const cajaInfo = document.getElementById('info-mapa');
  
  // ISLAS PRINCIPALES
  if (lugar === 'gran_malvina') {
    cajaInfo.innerHTML = "<strong>Isla Gran Malvina:</strong> Es la isla occidental y la segunda más grande del archipiélago. Su terreno es más montañoso que el de la Isla Soledad y está escasamente poblada, dedicada principalmente a la cría de ovejas.";
  } 
  else if (lugar === 'soledad') {
    cajaInfo.innerHTML = "<strong>Isla Soledad:</strong> Es la isla oriental, la más grande y poblada del archipiélago. Alberga la capital y fue el escenario principal del conflicto bélico de 1982.";
  }

  // ACCIDENTES GEOGRÁFICOS Y CUERPOS DE AGUA
  else if (lugar === 'estrecho_san_carlos') {
    cajaInfo.innerHTML = "<strong>Estrecho de San Carlos:</strong> Es el canal principal que separa la Isla Gran Malvina de la Isla Soledad. Fue un escenario naval clave durante el conflicto de 1982, conocido estratégicamente por las fuerzas británicas como el 'Callejón de las Bombas'.";
  }
  else if (lugar === 'bahia_9_julio') {
    cajaInfo.innerHTML = "<strong>Bahía 9 de Julio:</strong> Extensa bahía ubicada en el noroeste de la Isla Gran Malvina, caracterizada por su costa accidentada y su importancia para la protección de la fauna marina.";
  }
  else if (lugar === 'bahia_anunciacion') {
    cajaInfo.innerHTML = "<strong>Bahía de la Anunciación:</strong> Gran entrada de agua en el noreste de la Isla Soledad. Fue un punto históricamente importante para la navegación temprana y refugio de embarcaciones.";
  }
  else if (lugar === 'peninsula_san_luis') {
    cajaInfo.innerHTML = "<strong>Península de San Luis:</strong> Ubicada en el extremo noreste de la Isla Soledad. En esta zona se encontraba Puerto Soledad, el primer asentamiento español y argentino en las islas.";
  }

  // LOCALIZACIONES Y LOCALIDADES
  else if (lugar === 'puerto_argentino') {
    cajaInfo.innerHTML = "<strong>Puerto Argentino:</strong> Capital y principal localidad del archipiélago, ubicada al este de la Isla Soledad. Es el mayor asentamiento poblacional, puerto clave y centro administrativo de las islas.";
  }
  else if (lugar === 'puerto_mitre') {
    cajaInfo.innerHTML = "<strong>Puerto Mitre (Port Howard):</strong> Importante establecimiento ganadero y puerto ubicado en la costa este de la Isla Gran Malvina, justo frente al Estrecho de San Carlos.";
  }
  else if (lugar === 'puerto_darwin') {
    cajaInfo.innerHTML = "<strong>Puerto Darwin:</strong> Asentamiento ubicado en el istmo de Darwin, que conecta el norte y el sur de la Isla Soledad. Muy cerca se encuentra Pradera del Ganso (Goose Green), escenario de una importante batalla en 1982.";
  }
  else if (lugar === 'san_carlos') {
    cajaInfo.innerHTML = "<strong>San Carlos:</strong> Localidad en el noroeste de la Isla Soledad, en la costa del estrecho. Fue el principal punto de desembarco de las tropas británicas durante la guerra de las Malvinas.";
  }
  else if (lugar === 'puerto_san_carlos') {
    cajaInfo.innerHTML = "<strong>Puerto San Carlos:</strong> Pequeño asentamiento situado al norte de San Carlos, también en la costa occidental de la Isla Soledad, conocido por su valor estratégico.";
  }
  else if (lugar === 'isla_san_jose') {
    cajaInfo.innerHTML = "<strong>Isla San José (Weddell Island):</strong> Es la tercera isla más grande del archipiélago, ubicada al suroeste de la Gran Malvina. Se destaca por la variedad de fauna exótica introducida en el siglo XX.";
  }
  else if (lugar === 'fox_bay') {
    cajaInfo.innerHTML = "<strong>Bahía de los Zorros (Fox Bay):</strong> Importante asentamiento en el sur de la Gran Malvina, dividido por una bahía en dos partes (Este y Oeste). Es uno de los centros poblados más relevantes de esa isla.";
  }

  // OTRAS ISLAS MENORES Y CABOS
  else if (lugar === 'sebaldes') {
    cajaInfo.innerHTML = "<strong>Islas Sebaldes (Jason Islands):</strong> Archipiélago ubicado en el extremo noroeste. Es una zona remota y una reserva natural fundamental para la preservación de colonias de albatros y pingüinos.";
  }
  else if (lugar === 'trinidad') {
    cajaInfo.innerHTML = "<strong>Isla Trinidad (Saunders Island):</strong> Ubicada al norte de la Gran Malvina. Es de gran importancia histórica por haber albergado a Puerto Egmont, el primer asentamiento británico en 1765.";
  }
  else if (lugar === 'borbon') {
    cajaInfo.innerHTML = "<strong>Isla Borbón (Pebble Island):</strong> Situada al norte de la Gran Malvina. Es conocida por sus extensas playas de guijarros y por un audaz ataque comando sobre su pista de aterrizaje en 1982.";
  }
  else if (lugar === 'bougainville') {
    cajaInfo.innerHTML = "<strong>Isla Bougainville (Lively Island):</strong> Ubicada al sureste de la Isla Soledad. Es la isla más grande de su grupo y está orientada principalmente a la cría extensiva de ovejas.";
  }
  else if (lugar === 'jorge_aguila') {
    cajaInfo.innerHTML = "<strong>Isla Jorge e Isla Águila:</strong> Islas situadas al sur del archipiélago, separadas de la Isla Soledad por el Canal del Águila. Son áreas de gran valor ecológico para aves y lobos marinos.";
  }
  else if (lugar === 'cabo_leal') {
    cajaInfo.innerHTML = "<strong>Cabo Leal (Cape Carysfort):</strong> Un cabo prominente que marca uno de los puntos más salientes en el extremo noreste de la costa de la Isla Soledad.";
  }
  else if (lugar === 'cabo_belgrano') {
    cajaInfo.innerHTML = "<strong>Cabo Belgrano (Cape Meredith):</strong> Es el punto más meridional (al extremo sur) de la Isla Gran Malvina, donde la costa se encuentra con las agitadas aguas del océano.";
  }
  else if (lugar === 'roca_blanca') {
    cajaInfo.innerHTML = "<strong>Punta Roca Blanca:</strong> Formación costera en el norte del archipiélago, conocida por sus elevaciones rocosas que sirven como puntos de referencia marítimos en el área del estrecho.";
  }
}
